class RetryPolicy(StrEnum):
    AFTER_AUTHORITY_CHANGE = "after_authority_change"
    IF_IDEMPOTENT = "if_idempotent"
    NEVER = "never"
    WITH_FRESH_STATE = "with_fresh_state"


ERROR_RETRY: Final[dict[ErrorCode, RetryPolicy]] = {
    ErrorCode.ACCESS_DENIED: RetryPolicy.AFTER_AUTHORITY_CHANGE,
    ErrorCode.IFC_VIOLATION: RetryPolicy.AFTER_AUTHORITY_CHANGE,
    ErrorCode.CONCURRENT_CONFLICT: RetryPolicy.WITH_FRESH_STATE,
    ErrorCode.UNAVAILABLE: RetryPolicy.IF_IDEMPOTENT,
    ErrorCode.DEADLINE_EXCEEDED: RetryPolicy.IF_IDEMPOTENT,
    ErrorCode.EXPIRED: RetryPolicy.WITH_FRESH_STATE,
    ErrorCode.INVALID_INPUT: RetryPolicy.NEVER,
    ErrorCode.INVALID_RESULT: RetryPolicy.NEVER,
    ErrorCode.INTERNAL: RetryPolicy.NEVER,
}
